#!/usr/bin/env python3
"""Build dated static studies from the Oct 3 live public references.

Native Stitch exports are kept separately, unchanged. These corrections use
observed copy, official assets and responsive geometry; they are not accepted
copies of the original sites and do not connect to either product backend.
"""
from pathlib import Path
import html
import json

ROOT = Path(__file__).resolve().parents[1] / '.stitch-work/current-official'


def image(brand, name, alt='', cls=''):
    # Keep the original bytes and hashes in source, and stream four large
    # public illustrations to keep the existing Site within its archive limit.
    remote_hashicorp = {
        'infragraph.svg': 'https://www.datocms-assets.com/2885/1777397254-infragraph_hp.svg',
        'accelerate.webp': 'https://www.datocms-assets.com/2885/1772215414-accelerate-small-1.webp',
        'certification.svg': 'https://www.datocms-assets.com/2885/1758555867-homepage-in-content-02.svg',
        'identity.png': 'https://www.datocms-assets.com/2885/1754529481-identity-imagery-icon.png',
    }
    src = remote_hashicorp.get(name) if brand == 'hashicorp' else None
    src = src or f'{brand}-assets/{name}'
    return f'<img class="{cls}" src="{src}" alt="{html.escape(alt)}" loading="lazy">'


def link(label, url, cls=''):
    return f'<a class="{cls}" href="{html.escape(url)}">{html.escape(label)}</a>'


def page(brand, title, css, body, script):
    mobile_preloads = ''.join(f'<link rel="preload" as="image" href="lovable-assets/{name}" media="(max-width:767px)">' for name in ['e19ff4306f0fc197.svg', '8a1f34dfb6e0e696.svg']) if brand == 'lovable' else ''
    (ROOT / f'{brand}.html').write_text(f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>{title} · Unofficial visual study</title>{mobile_preloads}<style>{css}</style></head><body>{body}<script>{script}</script></body></html>''')


MENU_SCRIPT = '''
const toggle=document.querySelector('.menu-toggle'), menu=document.querySelector('.mobile-menu');
function setMenu(open){menu.hidden=!open;toggle.textContent=open?'×':'☰';toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close menu':'Open menu');document.body.style.overflow=open?'hidden':'';}
toggle.addEventListener('click',()=>setMenu(menu.hidden));
document.addEventListener('keydown',e=>{if(e.key==='Escape')setMenu(false)});
'''


